    // restGold(gold: Ganzzahl, preis: Ganzzahl): Ganzzahl
    // Ein Held kauft so viele Traenke zum Preis preis, wie sein Gold
    // reicht. Wie viel Gold bleibt uebrig? (preis > 0)
    public static int restGold(int gold, int preis) {
        // TODO Level 0.2 · Basis
        return -1;
    }

    // kistenBenoetigt(anzahl: Ganzzahl, proKiste: Ganzzahl): Ganzzahl
    // In eine Kiste passen proKiste Traenke. Wie viele Kisten braucht man
    // fuer anzahl Traenke? Eine angefangene Kiste zaehlt mit (aufrunden!).
    // anzahl >= 0, proKiste > 0. Ohne Math.ceil - nur mit / und %.
    public static int kistenBenoetigt(int anzahl, int proKiste) {
        // TODO Level 0.2 · Basis
        return -1;
    }


    // ================== Stufe ERWEITERUNG ==================

    // schadensstufe(schaden: Ganzzahl): Zeichenkette
    // "kein" (schaden <= 0), "leicht" (1 bis 9), "mittel" (10 bis 29),
    // "schwer" (ab 30).
    public static String schadensstufe(int schaden) {
        // TODO Level 0.2 · Erweiterung
        return "";
