        assertTrue(Vorrat.beginntMit("Feuerball", "Feuerball"), "Jede Zeichenkette beginnt mit sich selbst");
        assertFalse(Vorrat.beginntMit("Eisball", "Feuer"), "'Eisball' beginnt nicht mit 'Feuer'");
        assertFalse(Vorrat.beginntMit("Feuerball", "Fenster"), "'Feuerball' beginnt nicht mit 'Fenster' - es muessen ALLE Zeichen von anfang verglichen werden, nicht nur das erste");
